ritique doit être clarifiée avant toute sortie trompeuse.\n\nRECHERCHE ET OUTILS\nRecherche facultative : utilise-la seulement pour vérifier un fait important, actualiser une donnée ou combler une source identifiable; cite toute source utilisée. N’invente jamais de source, chiffre, citation, décision, clause, résultat de test ou information inaccessible.\n\nRÉFÉRENTIEL ET LIMITES\nAucun référentiel métier imposé; applique les conventions réellement utiles à la mission. Pour une mission juridique, médicale, financière ou réglementaire sensible, précise ce qui doit être validé par un professionnel compétent sans remplacer le livrable demandé.\n\nLIVRABLE ET MISE EN FORME\nLivre Fiche produit prête à publier avec titre, description et caractéristiques. Adapte la structure au canal et au destinataire. Si un PDF, Word, tableur ou autre fichier est demandé et que l’outil existe, crée réellement le fichier, vérifie son ouverture et sa mise en page. Le contenu final doit être directement copiable ou utilisable, sans commentaire parasite.\n\nCONTRÔLE QUALITÉ\nVérifie silencieusement l’objectif, les faits, calculs, sources, destinataire, ton, structure, cohérence, orthographe, répétitions, format et utilité. Contrôle spécifique : Aucune composition, certification, compatibilité ou accessoire inclus déduit d’une simple photo. Corrige avant livraison.\n\nSORTIE OBLIGATOIRE\nNe t’arrête pas à des conseils, un plan ou une liste d’idées si le livrable peut être produit. Si un outil ou une source n’est pas accessible, demande seulement l’élément indispensable ou livre une version exploitable avec les points à vérifier clairement signalés.","sha256":"c497f2a5109f3aaad7605acca1d97e4abae37202ce8cc0ca5805cee3fc657ba8"}]$raccourcia$::jsonb) as x(
  ref text, moteur text, payload text, sha256 text
);

do $ctrl$
begin
  if (select count(*) from lot_v5_payloads) <> 30 then
    raise exception 'Lot 231 tronque : % lignes au lieu de 30.',
      (select count(*) from lot_v5_payloads);
  end if;
end $ctrl$;

-- 1. L'ancien courant sort du courant.
update public.prompt_versions pv
set is_current = false, status = 'retired'::public.version_status
from lot_v5_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where pv.variant_id = v.id and pv.is_current and pv.payload is distinct from l.payload;

-- 2. Poser le nouveau texte la ou plus rien n'est courant.
insert into public.prompt_versions (variant_id, version_label, payload, status, is_current, published_at)
select v.id, 'v5-final', l.payload, 'published'::public.version_status, true, now()
from lot_v5_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where not exists (
  select 1 from public.prompt_versions pv where pv.variant_id = v.id and pv.is_current
);

-- 3. Un texte identique deja archive redevient le courant : rejouer le lot ne
--    cree pas une version de plus.
update public.prompt_versions pv
set is_current = true, status = 'published'::public.version_status
from lot_v5_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where pv.variant_id = v.id and pv.payload = l.payload and not pv.is_current
  and not exists (select 1 from public.prompt_versions a where a.variant_id = v.id and a.is_current);

do $ctrl$
declare
  v_pose integer;
begin
  select count(*) into v_pose
  from lot_v5_payloads l
  join public.prompts p on p.external_ref = l.ref
  join public.prompt_variants v on v.prompt_id = p.id
  join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
  join public.prompt_versions pv on pv.variant_id = v.id and pv.is_current
  where pv.payload = l.payload;
  if v_pose <> 30 then
    raise exception 'Lot 231 : % payloads courants sur 30.', v_pose;
  end if;
end $ctrl$;

drop table lot_v5_payloads;
